// Canonical typed error declarations for section 50.
// Like-class failures share a code while preserving cause and legal remedy in detail.
codes! {
    MessagingChannelRefused => ("messaging-channel-refused", Refused) {reason: MessagingChannelError, next_step:String} => "Messaging channel: {reason}", "{next_step}";
    AtlasSymbolAmbiguous => ("atlas-symbol-ambiguous", Usage) { symbol: String, candidates: Vec<String> } => "`{symbol}` names {candidates.len} symbols", "add `--path`";
    CommandRetired => ("command-retired", Usage) { old: String, reason: String, workflow: String } => "`{old}` was retired: {reason}", "{workflow}";
    CursorInvalid => ("cursor-invalid", Usage) { reason: String, next_step: String } => "this cursor isn't valid here ({reason})", "{next_step}";
    InputTooLarge => ("input-too-large", Usage) { field: String, limit_bytes: u64, got_bytes: u64 } => "{field} is {got_bytes} bytes; limit {limit_bytes}", "shorten or split it";
    InputUnknownField => ("input-unknown-field", Usage) { op: String, field: String, next_step: String } => "`{field}` is not accepted by {op}", "{next_step}";
    ProjectConflictsSession => ("project-conflicts-session", Usage) { flag_project: String, session_project: String } => "`-p {flag_project}` conflicts with this session's project {session_project}", "drop `-p`";
    ProjectRequired => ("project-required", Usage) { choices: Vec<ProjectChoice> } => "which project? {choices.len} registered: {choices}", "Select one with `se --project NAME …`, or use `se init` to register a project";
    Renamed => ("renamed", Usage) { old: String, replacement: String } => "`{old}` was renamed", "Use `{replacement}` (template; fill placeholders)";
    SelectorAmbiguous => ("selector-ambiguous", Usage) { kind: String, selector: String, matches: Vec<String> } => "{selector} matches {matches.len} {kind} entries: {matches}", "Select an exact ID from {matches}";
    UsageConflictingFlags => ("usage-conflicting-flags", Usage) { flags: Vec<String> } => "{flags} cannot be used together", "pick one";
    UsageInvalidValue => ("usage-invalid-value", Usage) { argument: String, got: String, expected: String } => "{argument}: `{got}` is not {expected}", "correct the value";
    UsageMissingArgument => ("usage-missing-argument", Usage) { command: String, argument: String } => "`{command}` needs {argument}", "Use `{command} --help`";
    UsageUnknownCommand => ("usage-unknown-command", Usage) { got: String, suggestion: Option<String> } => "unknown command `{got}`", "Use `se help`";
    UsageUnknownFlag => ("usage-unknown-flag", Usage) { flag: String, command: String, reason: String } => "`{command}` does not accept {flag}: {reason}", "Use `{command} --help`";
    CapabilityInvalid => ("capability-invalid", Unauthorized) { subject: String, reason: String, next_step: String } => "Session credential {subject}: {reason}", "{next_step}";
    GrantRequired => ("grant-required", Unauthorized) { grant: String, agent: AgentId } => "Session for {agent} lacks permission {grant}", "Owner: `se config set agent.{agent}.can-create true`";
    HumanTerminalRequired => ("human-terminal-required", Unauthorized) { op: String, reason: String } => "`{op}` needs you at an interactive terminal not started by an agent: {reason}", "Open your own terminal outside an agent tree; this mistake/drift guard is not proof against a determined agent using your account";
    ListenerAdmissionRefused => ("listener-admission-refused", Unauthorized) { reason: String } => "local server refused the request: {reason}", "Reconnect from a session started by `se launch AGENT`; use the credential for this data home and a loopback address. Remote Host or Origin values are refused.";
    MessageScopeDenied => ("message-scope-denied", Unauthorized) { filter: String, agent: AgentId } => "as an agent, {agent} can list only messages it sent or received; `{filter}` names others' mail", "Drop the filter, or the owner runs `se msg list` from their own terminal.";
    NotRecipient => ("not-recipient", Unauthorized) { message: MessageId, recipient: String } => "only {recipient} can mark {message} read or dismissed", "read it with `se msg read` as that agent, or leave it";
    OsUserMismatch => ("os-user-mismatch", Unauthorized) { expected: String, actual: String } => "this StateEngine home belongs to {expected}, you are {actual}", "use your own `SE_HOME`";
    OwnerRequired => ("owner-required", Unauthorized) { op: String } => "`{op}` is an owner command; agent sessions can't run it", "Use an owner terminal; unsetting SE_SESSION alone does not establish authority";
    SessionRequired => ("session-required", Unauthorized) { op: String } => "`{op}` acts as an agent and needs a launched session", "Use `se launch AGENT`";
    ApiVersionUnsupported => ("api-version-unsupported", Refused) { client: String, host: String } => "client API {client} vs runtime {host}", "upgrade the older side";
    AtlasFileOverBudget => ("atlas-file-over-budget", Refused) { path: String, size: u64, budget: u64 } => "{path} ({size}) exceeds the per-file parse budget", "none; the file stays text-searchable";
    AtlasIndexAbsent => ("atlas-index-absent", Refused) { project: ProjectId } => "no code index for {project} yet", "Indexing runs after host readiness by default; use `se status` for progress and inspect atlas.enabled in the selected config.toml if it was explicitly disabled";
    AtlasLanguageUnsupported => ("atlas-language-unsupported", Refused) { path: String, language: Option<String> } => "{language} files aren't parsed", "text search: `--kind text`";
    AtlasPathOutsideRoot => ("atlas-path-outside-root", Refused) { path: String, root: String } => "{path} is outside {root}", "use a project-relative path";
    BackupFailed => ("backup-failed", Refused) { path: String, step: String, reason: String } => "Backup {path} failed at {step}: {reason}", "Run `se doctor`; automatic backup or restore must verify before proceeding";
    BypassNotOptedIn => ("bypass-not-opted-in", Refused) { profile: String } => "full bypass is only allowed through a saved, named profile", "add `bypass = true` under `[profiles.NAME]`, then → `se config set agent.A.profile NAME`";
    CaptureConsentMissing => ("capture-consent-missing", Refused) { session: SessionId } => "capture is off for this session", "relaunch without `--incognito`";
    ConfigurationInvalid => ("configuration-invalid", Refused) { subject: String, reason: String, next_step: String } => "Configuration {subject}: {reason}", "{next_step}";
    DecisionStateInvalid => ("decision-state-invalid", Refused) { subject: String, reason: String, next_step: String } => "Decision transition {subject}: {reason}", "{next_step}";
    FeatureUnavailable => ("feature-unavailable", Refused) { subject: String, reason: String, next_step: String } => "Feature {subject}: {reason}", "{next_step}";
    ForgetNotCapturedRecord => ("forget-not-captured-record", Refused) { event: EventId, kind: String } => "only captured turns and messages can be erased; {event} is a {kind}", "pick a captured record";
    HomeUnsupportedLocation => ("home-unsupported-location", Refused) { home: String, kind: String } => "{home} is on a {kind} location; the store needs a local disk", "set `SE_HOME` to a local folder";
    ImportFormatUnsupported => ("import-format-unsupported", Refused) { path: String, found: String, supported: Vec<String> } => "{path} is format {found}; supported: {supported}", "upgrade Node StateEngine first, then import";
    ImportSourceActive => ("import-source-active", Refused) { path: String, pid: Option<u32> } => "the old StateEngine is still running on {path}", "stop it with the old `se down`, then retry";
    IntegrationFailed => ("integration-failed", Refused) { subject: String, reason: String, next_step: String } => "Integration {subject}: {reason}", "{next_step}";
    JobBreakawayRefused => ("job-breakaway-refused", Refused) { parent: String } => "Windows refused job breakaway for a detached process launched by {parent}", "Open Windows Terminal or PowerShell directly from Start using this Windows account, then rerun the command there; an IDE, CI runner or runas terminal can inherit a job that forbids detached launches";
    LaunchFailed => ("launch-failed", Refused) { subject: String, reason: String, next_step: String } => "Launch {subject}: {reason}", "{next_step}";
    ListenerUnavailable => ("listener-unavailable", Refused) { subject: String, reason: String, next_step: String } => "Listener {subject}: {reason}", "{next_step}";
    ProjectRemoved => ("project-removed", Refused) { project: ProjectId, at: UnixMicros } => "project {project} was removed at {at}", "re-adopt: → `se init --repo {root}`";
    ProviderChangeBreaksResume => ("provider-change-breaks-resume", Refused) { agent: AgentId, saved: String, requested: String } => "{agent}'s conversation is a {saved} conversation", "Use `se launch {agent} --new --provider {requested}`";
    ProviderCliNotFound => ("provider-cli-not-found", Refused) { provider: String, searched: Vec<String> } => "can't find the {provider} CLI", "Install the {provider} CLI, add its native executable to PATH or set command under [providers.{provider}] in the runtime's selected configuration (SE_CONFIG, otherwise this home's config.toml), then restart with the same selection and retry the launch";
    ProviderIncompatible => ("provider-incompatible", Refused) { subject: String, reason: String, next_step: String } => "Provider {subject}: {reason}", "{next_step}";
    RecipientOtherProject => ("recipient-other-project", Refused) { to: String, project: ProjectId } => "{to} is in project {project}", "send from that project";
    RepairRefused => ("repair-refused", Refused) { subject: String, reason: String, next_step: String } => "Repair {subject}: {reason}", "{next_step}";
    RepoInvalid => ("repo-invalid", Refused) { subject: String, reason: String, next_step: String } => "Repository {subject}: {reason}", "{next_step}";
    ResumeReferenceMissing => ("resume-reference-missing", Refused) { agent: AgentId } => "{agent}'s previously saved conversation reference is missing", "Use `se launch {agent} --new`";
    RuntimeIncompatible => ("runtime-incompatible", Refused) { subject: String, reason: String, next_step: String } => "Runtime {subject}: {reason}", "{next_step}";
    SecretToTerminalRefused => ("secret-to-terminal-refused", Refused) { what: String } => "refusing to print {what} to a terminal", "run it through a pipe (integrations only)";
    SessionAlreadyEnded => ("session-already-ended", Refused) { session: SessionId, at: UnixMicros } => "session {session} ended at {at}", "Use `se launch AGENT`";
    SetupRequired => ("setup-required", Refused) { subject: String, reason: String, next_step: String } => "Setup {subject}: {reason}", "{next_step}";
    StoreMigrationFailed => ("store-migration-failed", Refused) { from: u64, to: u64, step: String, rollback_copy: String } => "upgrade {from}→{to} failed at {step}; old copy kept at {rollback_copy}", "Use `se doctor`";
    StoreReadOnly => ("store-read-only", Refused) { path: String } => "{path} is read-only", "fix permissions or `SE_HOME`";
    StoreTooNew => ("store-too-new", Refused) { store_version: u64, supported: u64 } => "the store was written by a newer se (schema {store_version})", "Upgrade se; unsupported migration paths refuse without modifying the source store";
    WakeNotRunning => ("wake-not-running", Refused) { agent: AgentId } => "{agent} isn't running, so there is nothing to wake", "Use `se launch {agent}`";
    WindowUnavailable => ("window-unavailable", Refused) { tried: Vec<String> } => "no terminal window could be opened ({tried})", "Use `se launch AGENT --detach`, or set `launch.terminal`";
    AgentUnknown => ("agent-unknown", Unknown) { selector: String, suggestion: Option<String> } => "no agent `{selector}` in {project}", "Use `se agent list`";
    AtlasPathUnknown => ("atlas-path-unknown", Unknown) { path: String } => "{path} isn't indexed", "Check the repository path and its spelling; use local file search if the code index has no entry.";
    AtlasSymbolUnknown => ("atlas-symbol-unknown", Unknown) { symbol: String } => "no symbol `{symbol}`", "Check the symbol spelling or search the repository text directly.";
    CommittedResponseUnavailable => ("committed-response-unavailable", Incomplete) { operation: Box<str>, key: Option<String>, natural_events: Box<[EventId]>, committed_events: Box<[EventId]>, reason: Box<str> } => "Commit confirmed for {operation}; continuation failed: {reason}; original key {key}, natural events {natural_events}", "Rerun the same command with --key K (CLI), substituting the original detail.key, or repeat the call with the same idempotency_key (MCP) to read the confirmed receipt; natural capture/markers replay the original natural_events unchanged";
    CaptureIncomplete => ("capture-incomplete", Incomplete) { committed_events: Vec<EventId>, natural_keys: Vec<String>, reason: String } => "Capture stopped after committed events {committed_events}, natural keys {natural_keys}: {reason}", "Repeat the same hook with its original session/provider/turn identities; already committed turns replay";
    CommitOutcomeUnknown => ("commit-outcome-unknown", Unknown) { operation: String, key: Option<String>, natural_events: Vec<EventId> } => "Commit outcome unknown for {operation}; original key {key}, natural events {natural_events}", "Rerun the same command with --key K (CLI), substituting the original detail.key, or repeat the call with the same idempotency_key (MCP); natural capture/markers replay the original natural_events unchanged";
    TargetUnknown => ("target-unknown", Unknown) { subject: String, reason: String, next_step: String } => "Unknown target {subject}: {reason}", "{next_step}";
    AtlasSourceUnreadable => ("atlas-source-unreadable", Unreadable) { path: String, reason: String } => "Atlas can't read {path}: {reason}", "restore read access to the file";
    AtlasUnreadable => ("atlas-unreadable", Unreadable) { path: String, reason: String } => "can't read the index database atlas.db: {reason}", "Run `se doctor`; only a diagnosed atlas.index repair may rebuild atlas.db; source-file unreadability is separate";
    ResumeReferenceUnverifiable => ("resume-reference-unverifiable", Unreadable) { agent: AgentId, conversation: String, reason: String } => "can't verify conversation {conversation}: {reason}", "Use `se launch {agent} --new` (starts fresh, explicitly)";
    SourceUnreadable => ("source-unreadable", Unreadable) { subject: String, reason: String, next_step: String } => "Cannot read {subject}: {reason}", "{next_step}";
    StoreCorrupt => ("store-corrupt", Unreadable) { path: String, check: String } => "the store failed its integrity check ({check})", "Stop all writers and preserve the damaged database with its WAL/SHM. Run `se status` in your own terminal with the same --home for executable restore or separate fresh-home commands; choose a CLOSED retained copy. No automatic backup selection or salvage is performed";
    StoreUnreadable => ("store-unreadable", Unreadable) { path: String, reason: String } => "can't read the store: {reason}", "Use `se doctor`";
    AgentNameConflict => ("agent-name-conflict", Conflict) { name: String, agent: AgentId, project: ProjectId } => "Agent name `{name}` already belongs to {agent} in project {project}", "Choose another name for the new agent, or use the existing agent";
    AgentAlreadyRunning => ("agent-already-running", Conflict) { agent: AgentId, pid: u32, since: String } => "{agent} is already running (since {since})", "message it, or → `se stop {agent}`";
    IdempotencyKeyReused => ("idempotency-key-reused", Conflict) { key: String, original_event: EventId } => "key `{key}` was used for a different request", "use a new key";
    IntegrationConflict => ("integration-conflict", Conflict) { path: String, entry: String } => "you changed {entry} in {path}; StateEngine won't overwrite it", "keep it, or delete the entry and → `se doctor --fix CHECK-ID`";
    LaunchInFlight => ("launch-in-flight", Conflict) { agent: AgentId, launch_id: LaunchId } => "{agent} is already being launched", "retry";
    RevisionConflict => ("revision-conflict", Conflict) { entity: String, expected: String, current: String } => "{entity} changed (you had revision {expected}, now {current})", "reread: → `se working-state` / `se decision show ID`";
    StateConflict => ("state-conflict", Conflict) { subject: String, reason: String, next_step: String } => "State conflict {subject}: {reason}", "{next_step}";
    AtlasIndexing => ("atlas-indexing", Incomplete) { indexed: u64, total: u64 } => "index is {indexed}/{total} files; results may be partial", "retry later";
    AtlasParseFailed => ("atlas-parse-failed", Incomplete) { path: String, language: String, reason: String } => "Atlas couldn't parse {path} ({language}): {reason}", "Results for this file use bounded text search. Run `se doctor` and include this diagnostic when reporting the problem.";
    CursorExpired => ("cursor-expired", Incomplete) { oldest_available: Cursor } => "the cursor is older than retained history", "remove or replace the invalid `--cursor` (list pagination) or `--since` (history position)";
    ForgetIncomplete => ("forget-incomplete", Incomplete) { erased: Vec<String>, residual: Vec<String> } => "erased in the store; copies remain in {residual}", "delete or let backups expire; provider transcripts belong to Claude/Codex";
    ImportIncomplete => ("import-incomplete", Incomplete) { families: Vec<ImportFamilyIssue> } => "import finished with rejected rows", "rerun (idempotent); see the receipt";
    LaunchReadinessTimeout => ("launch-readiness-timeout", Incomplete) { agent: AgentId, waited_ms: u64, last_observed: String } => "{agent} started but wasn't ready after {waited_ms} ms", "Use `se agent show {agent}`";
    RemoveIncomplete => ("remove-incomplete", Incomplete) { stopped: Vec<String>, unwitnessed: Vec<String>, remaining: Vec<String> } => "removal partly done: {remaining}", "Use `se remove -p P` (idempotent)";
    RuntimeStartPending => ("runtime-start-pending", Incomplete) { waited_ms: u64 } => "the runtime is still starting after {waited_ms} ms", "Use `se status`";
    StopUnwitnessed => ("stop-unwitnessed", Incomplete) { scope: String, reason: String, remaining: Vec<String> } => "Stop of {scope} is unconfirmed: {reason}; named remaining {remaining}", "Read `se status` and retry the same keyed stop; for an uncontained group after a stop that could not be proved (StopUnproved only), owner-human `se stop AGENT --release` relinquishes ownership without signalling or proving exit";
    TranscriptTruncated => ("transcript-truncated", Incomplete) { path: String, offset: u64, size: u64 } => "{path} shrank below the read offset", "captured turns stay; → `se status`";
    AtlasResourceBudget => ("atlas-resource-budget", Unavailable) { resource: String, requested: u64, available: u64 } => "Atlas can't index right now: {resource} needs {requested}, {available} available", "Wait for memory pressure to ease, or search the repository text directly.";
    DeadlineExceeded => ("deadline-exceeded", Unavailable) { op: String, deadline_ms: u64 } => "`{op}` didn't finish in {deadline_ms} ms", "retry";
    IpcUnavailable => ("ipc-unavailable", Unavailable) { endpoint: String, reason: String } => "can't reach the runtime: {reason}", "Use `se status`";
    RuntimeHandoverInProgress => ("runtime-handover-in-progress", Unavailable) { generation: String } => "the runtime is changing hosts", "retry (`WhenRuntimeReady`)";
    RuntimeNotRunning => ("runtime-not-running", Unavailable) { op: String, reason: String } => "`{op}` needs a ready runtime writer: {reason}", "Reopen the current runtime generation and retry with the original request identity; use `se up` if no runtime is running";
    RuntimeStartFailed => ("runtime-start-failed", Unavailable) { reason: String, log: String } => "the runtime didn't start: {reason}", "see {log}; → `se doctor`";
    SessionNotActive => ("session-not-active", Unavailable) { subject: String } => "Session {subject} is not active yet", "Retry after the session activates";
    StoreBusy => ("store-busy", Unavailable) { waited_ms: u64, reason: String, next_step: String, replay: Option<Box<WriteRetryIdentity>> } => "Store unavailable after {waited_ms} ms: {reason}", "{next_step}; retry the same request identity";
    StoreDiskFull => ("store-disk-full", Unavailable) { path: String, free_bytes: Option<u64> } => "not enough disk space at {path}", "Free space on the named volume, then retry the same command with its original --key or idempotency_key. Replaying that same key is safe; preserve the store and WAL/SHM files.";
    StoreMigrationRequired => ("store-migration-required", Unavailable) { from: u64, to: u64 } => "Store {from} needs supported additive migration to {to}", "Start `se up`: the sole owning host verifies a pre-migration backup and migrates automatically; an old running host requires `se down` first";
    Internal => ("internal", Internal) { report_id: String, location: String } => "StateEngine hit a bug ({report_id})", "Run `se doctor` and include its output and report ID {report_id} when reporting the bug.";
    Cancelled => ("cancelled", Cancelled) { op: String } => "`{op}` was interrupted", "rerun; writes are all-or-nothing";
}
